// 24-S3 acceptance: the localStorage journal, per puzzle and epoch
// (`journal.ts`). Do not edit this file to match an implementation.
import { describe, expect, it } from 'vitest';
import { journalKey, readJournal, removeJournalKeys, writeJournal, type JournalStorage } from './journal';
import type { Operation } from './operation';

function memory(): JournalStorage & { data: Map<string, string> } {
  const data = new Map<string, string>();
  return {
    data,
    get length() { return data.size; },
    key: (index) => [...data.keys()][index] ?? null,
    getItem: (key) => data.get(key) ?? null,
    setItem: (key, value) => { data.set(key, value); },
    removeItem: (key) => { data.delete(key); },
  };
}
const op = (opId: string, epoch: number, puzzleId = 'p1', clientId = 'tab-a'): Operation =>
  ({ opId, puzzleId, clientId, epoch, baseVersion: 0, kind: 'title', title: opId });

describe('24-S3-8 the journal', () => {
  it('keeps a tab’s operations per puzzle and epoch, and drops the epochs it no longer has', () => {
    const store = memory();
    writeJournal(store, 'p1', 'tab-a', [op('a', 0), op('b', 1)], 10);
    expect([...store.data.keys()].sort()).toEqual([journalKey('p1', 0, 'tab-a'), journalKey('p1', 1, 'tab-a')].sort());
    writeJournal(store, 'p1', 'tab-a', [op('b', 1)], 11);
    expect([...store.data.keys()]).toEqual([journalKey('p1', 1, 'tab-a')]);
    writeJournal(store, 'p1', 'tab-a', [], 12);
    expect(store.data.size).toBe(0);
  });

  it('reads every tab’s journal for the puzzle: older epochs first, then by when written, each in order, once each', () => {
    const store = memory();
    writeJournal(store, 'p1', 'tab-b', [op('b1', 1, 'p1', 'tab-b'), op('b2', 1, 'p1', 'tab-b')], 20);
    writeJournal(store, 'p1', 'tab-a', [op('a1', 1), op('a0', 0)], 10);
    writeJournal(store, 'p1', 'tab-c', [op('b1', 1, 'p1', 'tab-b')], 30);
    writeJournal(store, 'p2', 'tab-a', [op('other', 0, 'p2')], 5);
    const { ops, keys } = readJournal(store, 'p1');
    expect(ops.map((o) => o.opId)).toEqual(['a0', 'a1', 'b1', 'b2']);
    expect(ops[0]).toEqual(op('a0', 0));
    expect(keys).toHaveLength(4);
    expect(keys.some((key) => key.includes(':p2:'))).toBe(false);
    removeJournalKeys(store, keys);
    expect([...store.data.keys()]).toEqual([journalKey('p2', 0, 'tab-a')]);
  });

  it('skips malformed entries, malformed operations and another puzzle’s operations', () => {
    const store = memory();
    store.setItem(journalKey('p1', 0, 'x'), 'not json');
    store.setItem(journalKey('p1', 0, 'y'), JSON.stringify({ savedAt: 1, ops: [{ kind: 'title' }, op('good', 0), op('stray', 0, 'p9')] }));
    store.setItem('crossward:journal:v1:p1:nope:z', JSON.stringify({ savedAt: 1, ops: [op('bad-key', 0)] }));
    expect(readJournal(store, 'p1').ops.map((o) => o.opId)).toEqual(['good']);
  });

  it('a failing storage never throws', () => {
    const broken: JournalStorage = {
      length: 1, key: () => { throw new Error('denied'); }, getItem: () => { throw new Error('denied'); },
      setItem: () => { throw new Error('full'); }, removeItem: () => { throw new Error('denied'); },
    };
    expect(() => writeJournal(broken, 'p1', 'tab', [op('a', 0)])).not.toThrow();
    expect(readJournal(broken, 'p1')).toEqual({ ops: [], keys: [] });
    expect(() => removeJournalKeys(broken, ['k'])).not.toThrow();
  });
});
